/* ---- Form Data Cover: isi dropdown Bulan & Tahun, paksa huruf besar Nama Stasiun ---- */
const BULAN_LIST = ['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
BULAN_LIST.forEach((b, i) => {
  const opt = document.createElement('option');
  opt.value = String(i + 1).padStart(2, '0');
  opt.textContent = b;
  bulanSelect.appendChild(opt);
});

const CURRENT_YEAR = new Date().getFullYear();
for(let y = CURRENT_YEAR - 1; y <= CURRENT_YEAR + 4; y++){
  const opt = document.createElement('option');
  opt.value = String(y);
  opt.textContent = String(y);
  if(y === CURRENT_YEAR) opt.selected = true;
  tahunSelect.appendChild(opt);
}
// default: bulan berjalan terpilih otomatis
bulanSelect.value = String(new Date().getMonth() + 1).padStart(2, '0');

namaStasiun.addEventListener('input', () => {
  const pos = namaStasiun.selectionStart;
  namaStasiun.value = namaStasiun.value.toUpperCase();
  namaStasiun.setSelectionRange(pos, pos);
});

function getCoverData(){
  return {
    jenisDinasan: jenisDinasan.value,
    namaStasiun: namaStasiun.value.trim(),
    bulan: bulanSelect.value,
    bulanLabel: BULAN_LIST[parseInt(bulanSelect.value, 10) - 1] || '',
    tahun: tahunSelect.value
  };
}

/* ---- Cover halaman pertama: template Danantara/KAI + overlay data dinamis ---- */
const COVER_TEMPLATE_SRC = "data:image/webp;base64,";
const COVER_IMG_W = 1086, COVER_IMG_H = 1448;
const COVER_NAVY = '#05215B';
const COVER_GRAY = '#343435';
// Area (koordinat piksel pada gambar asli 1086x1448) yang ditimpa warna putih lalu diisi teks baru.
// Batas x/y sudah disesuaikan agar tidak menabrak garis dekoratif atap di kanan maupun divider tipis.
const COVER_REGIONS = {
  jenis:   { maskX0:150, maskY0:495, maskX1:930, maskY1:645, cy:570, maxTextW:760, fontPx:104, weight:800, color:COVER_NAVY, letterSpacing:1 },
  stasiun: { maskX0:150, maskY0:680, maskX1:895, maskY1:820, cy:750, maxTextW:720, fontPx:104, weight:800, color:COVER_NAVY, letterSpacing:1 },
  bulan:   { maskX0:250, maskY0:850, maskX1:890, maskY1:945, cy:903, maxTextW:600, fontPx:65,  weight:600, color:COVER_GRAY, letterSpacing:0.5 }
};

let coverTemplateImg = null;
function loadCoverTemplate(){
  if(coverTemplateImg) return Promise.resolve(coverTemplateImg);
  return new Promise((resolve, reject)=>{
    const img = new Image();
    img.onload = ()=>{ coverTemplateImg = img; resolve(img); };
    img.onerror = reject;
    img.src = COVER_TEMPLATE_SRC;
  });
}

// Tulis teks uppercase yang otomatis mengecil (auto-fit) supaya tidak melebihi maxW, lalu digambar center.
function drawFitText(ctx, text, cx, cy, maxW, fontPx, weight, family, color, letterSpacing){
  let size = fontPx;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = color;
  if('letterSpacing' in ctx) ctx.letterSpacing = letterSpacing + 'px';
  while(size > fontPx * 0.35){
    ctx.font = weight + ' ' + size + 'px ' + family;
    if(ctx.measureText(text).width <= maxW) break;
    size -= 2;
  }
  ctx.font = weight + ' ' + size + 'px ' + family;
  ctx.fillText(text, cx, cy);
  if('letterSpacing' in ctx) ctx.letterSpacing = '0px';
}

// Bangun canvas cover A4 penuh (sudah termasuk letterbox putih), siap ditambahkan sebagai halaman pertama.
async function buildCoverCanvas(coverData, dpi){
  const img = await loadCoverTemplate();
  await document.fonts.load('800 104px Inter');
  await document.fonts.load('600 65px Inter');
  try{ await document.fonts.ready; }catch(e){}

  const A4_MM = { w: 210, h: 297 };
  const a4w = Math.round(A4_MM.w / 25.4 * dpi);
  const a4h = Math.round(A4_MM.h / 25.4 * dpi);
  const fitScale = Math.min(a4w / COVER_IMG_W, a4h / COVER_IMG_H);
  const drawW = COVER_IMG_W * fitScale;
  const drawH = COVER_IMG_H * fitScale;
  const offsetX = (a4w - drawW) / 2;
  const offsetY = (a4h - drawH) / 2;

  const canvas = document.createElement('canvas');
  canvas.width = a4w; canvas.height = a4h;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#FFFFFF';
  ctx.fillRect(0, 0, a4w, a4h);
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = 'high';
  ctx.drawImage(img, 0, 0, COVER_IMG_W, COVER_IMG_H, offsetX, offsetY, drawW, drawH);

  // map koordinat piksel gambar asli -> koordinat canvas final
  const mapX = ox => offsetX + ox * fitScale;
  const mapY = oy => offsetY + oy * fitScale;

  const fields = [
    { region: COVER_REGIONS.jenis,   text: (coverData.jenisDinasan || '').toUpperCase() },
    { region: COVER_REGIONS.stasiun, text: (coverData.namaStasiun || '').toUpperCase() },
    { region: COVER_REGIONS.bulan,   text: coverData.bulanLabel ? (coverData.bulanLabel.toUpperCase() + ' - ' + coverData.tahun) : '' }
  ];

  fields.forEach(f=>{
    if(!f.text) return;
    const r = f.region;
    // timpa area placeholder lama dengan putih
    ctx.fillStyle = '#FFFFFF';
    ctx.fillRect(mapX(r.maskX0), mapY(r.maskY0), mapX(r.maskX1) - mapX(r.maskX0), mapY(r.maskY1) - mapY(r.maskY0));
    // gambar teks baru, auto-fit ke lebar maksimal
    drawFitText(
      ctx, f.text,
      mapX((r.maskX0 + r.maskX1) / 2), mapY(r.cy),
      r.maxTextW * fitScale, r.fontPx * fitScale, r.weight, 'Inter, sans-serif', r.color, r.letterSpacing * fitScale
    );
  });

  return canvas;
}
let zipFiles = [];      // { id, file }
let resultBlobUrl = null;
let isProcessing = false;

/* ---- Daftar Hadir / Daftar Dinasan: upload foto (opsional), jadi halaman ke-2 ---- */
const attendanceDrop = document.getElementById('attendanceDrop');
const attendanceInput = document.getElementById('attendanceInput');
const attendanceList = document.getElementById('attendanceList');
let attendancePhotos = []; // { id, file, url }

function addAttendancePhotos(files){
  const f = [...files].find(x => x.type && x.type.startsWith('image/'));
  if(!f) return;
  // hanya 1 foto diperbolehkan — foto baru menggantikan yang lama
  attendancePhotos.forEach(p => URL.revokeObjectURL(p.url));
  attendancePhotos = [{ id: 'a' + Math.random().toString(36).slice(2), file: f, url: URL.createObjectURL(f) }];
  renderAttendanceList();
}

function renderAttendanceList(){
  attendanceList.innerHTML = attendancePhotos.map(p => `
    <div class="photo-chip" data-id="${p.id}">
      <img class="photo-thumb" src="${p.url}" alt="${escapeHtml(p.file.name)}">
      <button class="remove" data-remove="${p.id}" title="Hapus">✕</button>
      <div class="fname">${escapeHtml(p.file.name)}</div>
    </div>
  `).join('');
}

attendanceList.addEventListener('click', e=>{
  const btn = e.target.closest('[data-remove]');
  if(!btn) return;
  const id = btn.dataset.remove;
  const idx = attendancePhotos.findIndex(p => p.id === id);
  if(idx >= 0){
    URL.revokeObjectURL(attendancePhotos[idx].url);
    attendancePhotos.splice(idx, 1);
    renderAttendanceList();
  }
});

['dragenter','dragover'].forEach(evt=>{
  attendanceDrop.addEventListener(evt, e=>{ e.preventDefault(); attendanceDrop.classList.add('drag'); });
});
['dragleave','drop'].forEach(evt=>{
  attendanceDrop.addEventListener(evt, e=>{ e.preventDefault(); attendanceDrop.classList.remove('drag'); });
});
attendanceDrop.addEventListener('drop', e=>{
  addAttendancePhotos([...e.dataTransfer.files]);
});
attendanceInput.addEventListener('change', e=>{
  addAttendancePhotos([...e.target.files]);
  attendanceInput.value = '';
});

function loadImageFile(file){
  return new Promise((resolve, reject)=>{
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = ()=>{ URL.revokeObjectURL(url); resolve(img); };
    img.onerror = ()=>{ URL.revokeObjectURL(url); reject(new Error('Gagal memuat foto ' + file.name)); };
    img.src = url;
  });
}

// Bangun canvas A4 landscape dari foto Daftar Hadir. Foto potret otomatis dirotasi 90° agar mengisi halaman landscape.
async function buildAttendanceCanvas(file, dpi){
  const img = await loadImageFile(file);
  const srcW = img.naturalWidth, srcH = img.naturalHeight;

  let work = document.createElement('canvas');
  if(srcH > srcW){
    // potret -> rotasi 90° agar jadi landscape
    work.width = srcH;
    work.height = srcW;
    const wctx = work.getContext('2d');
    wctx.save();
    wctx.translate(work.width / 2, work.height / 2);
    wctx.rotate(90 * Math.PI / 180);
    wctx.drawImage(img, -srcW / 2, -srcH / 2);
    wctx.restore();
  } else {
    work.width = srcW;
    work.height = srcH;
    work.getContext('2d').drawImage(img, 0, 0);
  }

  const A4_MM = { w: 210, h: 297 };
  const a4wmm = A4_MM.h, a4hmm = A4_MM.w; // landscape: lebar 297mm, tinggi 210mm
  const a4w = Math.round(a4wmm / 25.4 * dpi);
  const a4h = Math.round(a4hmm / 25.4 * dpi);
  const fitScale = Math.min(a4w / work.width, a4h / work.height);
  const drawW = work.width * fitScale;
  const drawH = work.height * fitScale;
  const offsetX = (a4w - drawW) / 2;
  const offsetY = (a4h - drawH) / 2;

  const final = document.createElement('canvas');
  final.width = a4w;
  final.height = a4h;
  const fctx = final.getContext('2d');
  fctx.fillStyle = '#FFFFFF';
  fctx.fillRect(0, 0, a4w, a4h);
  fctx.imageSmoothingEnabled = true;
  fctx.imageSmoothingQuality = 'high';
  fctx.drawImage(work, 0, 0, work.width, work.height, offsetX, offsetY, drawW, drawH);
  freeCanvas(work); // kanvas rotasi sementara tidak diperlukan lagi setelah dipindah ke 'final'
  return final;
}

dpiOptions.addEventListener('click', (e)=>{
  if(isProcessing) return;
  const card = e.target.closest('.option-card');
  if(!card) return;
  [...dpiOptions.children].forEach(c => c.classList.remove('active'));
  card.classList.add('active');
  selectedDpi = parseInt(card.dataset.dpi, 10);
  dpiBadge.textContent = selectedDpi + ' DPI';
});

['dragenter','dragover'].forEach(evt=>{
  drop.addEventListener(evt, e=>{ e.preventDefault(); drop.classList.add('drag'); });
});
['dragleave','drop'].forEach(evt=>{
  drop.addEventListener(evt, e=>{ e.preventDefault(); drop.classList.remove('drag'); });
});
drop.addEventListener('drop', e=>{
  addZipFiles([...e.dataTransfer.files].filter(f => f.name.toLowerCase().endsWith('.zip')));
});
zipInput.addEventListener('change', e=>{
  addZipFiles([...e.target.files]);
  zipInput.value = '';
});

function addZipFiles(files){
  for(const f of files){
    zipFiles.push({ id: 'z' + Math.random().toString(36).slice(2), file: f });
  }
  renderZipList();
}

function renderZipList(){
  zipList.innerHTML = zipFiles.map(z => `
    <span class="zip-chip">${escapeHtml(z.file.name)}
      <button type="button" data-remove="${z.id}" title="Hapus">✕</button>
    </span>
  `).join('');
  processBtn.disabled = zipFiles.length === 0;
}

zipList.addEventListener('click', (e)=>{
  const btn = e.target.closest('button[data-remove]');
  if(!btn) return;
  zipFiles = zipFiles.filter(z => z.id !== btn.dataset.remove);
  renderZipList();
});

function escapeHtml(s){
  return s.replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

resetBtn.addEventListener('click', ()=>{
  zipFiles = [];
  renderZipList();
  attendancePhotos.forEach(p => URL.revokeObjectURL(p.url));
  attendancePhotos = [];
  renderAttendanceList();
  progressPanel.classList.remove('show');
  logEl.innerHTML = '';
  summaryEl.style.display = 'none';
  downloadRow.style.display = 'none';
  resetBtn.style.display = 'none';
  if(resultBlobUrl){ URL.revokeObjectURL(resultBlobUrl); resultBlobUrl = null; }
  setPill('idle');
  setProgress(0);
});

processBtn.addEventListener('click', ()=>{
  if(isProcessing || zipFiles.length === 0) return;
  runPipeline();
});

function setPill(stage){
  statusPill.classList.remove('processing','done','error');
  if(stage === 'idle'){ statusLabel.textContent = 'Menunggu'; }
  if(stage === 'processing'){ statusLabel.textContent = 'Memproses'; statusPill.classList.add('processing'); }
  if(stage === 'done'){ statusLabel.textContent = 'Selesai'; statusPill.classList.add('done'); }
  if(stage === 'error'){ statusLabel.textContent = 'Gagal'; statusPill.classList.add('error'); }
  // Anjuran "jangan tutup tab" hanya relevan selama proses berjalan.
  const warning = document.getElementById('processingWarning');
  if(warning){ warning.style.display = (stage === 'processing') ? 'flex' : 'none'; }
}
function setStatusMsg(msg){ statusMsg.textContent = msg || ''; }
function setProgress(pct){ progressFill.style.width = Math.max(0, Math.min(100, pct)) + '%'; }
function log(msg, kind){
  const row = document.createElement('div');
  row.className = 'log-row' + (kind ? ' ' + kind : '');
  row.innerHTML = '<span class="dot"></span><span>' + escapeHtml(msg) + '</span>';
  logEl.appendChild(row);
  logEl.scrollTop = logEl.scrollHeight;
}
// yieldUI() memberi jeda ke browser di tengah proses berat agar UI tidak freeze total.
// Dulu pakai setTimeout(fn, 0), tapi browser (Chrome/Firefox/Safari) sengaja memperlambat
// setTimeout saat tab tidak aktif/di background untuk hemat baterai — bisa bikin proses
// "kelihatan macet" begitu user pindah tab. MessageChannel jauh lebih tidak kena
// throttling ini (teknik yang sama dipakai library seperti scheduler React), jadi
// urutan/kecepatan proses tetap sama, cuma cara "menjeda"-nya yang lebih tahan banting.
const _yieldChannel = new MessageChannel();
const _yieldQueue = [];
_yieldChannel.port1.onmessage = () => {
  const resolve = _yieldQueue.shift();
  if(resolve) resolve();
};
function yieldUI(){
  return new Promise(resolve => {
    _yieldQueue.push(resolve);
    _yieldChannel.port2.postMessage(null);
  });
}

// Melepas buffer piksel kanvas besar (c1/c2/crop/stack) begitu tidak dipakai lagi,
// supaya browser bisa garbage-collect lebih cepat dan RAM tidak menumpuk di PC spek rendah.
function freeCanvas(c){
  if(!c) return;
  c.width = 0;
  c.height = 0;
}

async function runPipeline(){
  isProcessing = true;
  processBtn.disabled = true;
  resetBtn.style.display = 'none';
  dpiOptions.style.pointerEvents = 'none';
  progressPanel.classList.add('show');
  logEl.innerHTML = '';
  summaryEl.style.display = 'none';
  downloadRow.style.display = 'none';
  setPill('processing');
  setProgress(0);
  if(resultBlobUrl){ URL.revokeObjectURL(resultBlobUrl); resultBlobUrl = null; }

  const dpi = selectedDpi;
  const skipped = [];      // { name, reason }
  let duplicateCount = 0;
  const candidates = new Map(); // key(date_id) -> { name, date, id, zipName, entry }

  try{
    // ---- Phase 1: read all ZIPs, collect matching root-level PDF entries ----
    setStatusMsg('Membaca isi ZIP…');
    for(const z of zipFiles){
      log('Membuka ' + z.file.name + '…');
      await yieldUI();
      let jszip;
      try{
        jszip = await JSZip.loadAsync(z.file);
      }catch(err){
        log('Gagal membuka ' + z.file.name + ': ' + err.message, 'err');
        continue;
      }
      jszip.forEach((relPath, entry) => {
        if(entry.dir) return;
        if(relPath.includes('/')) return; // bukan di root ZIP
        if(!/\.pdf$/i.test(relPath)) return; // abaikan file non-pdf
        const m = relPath.match(NAME_RE);
        if(!m){
          skipped.push({ name: relPath + ' (' + z.file.name + ')', reason: 'Format nama tidak sesuai' });
          return;
        }
        const [, dd, mm, yyyy, id] = m;
        const dateKey = yyyy + '-' + mm + '-' + dd;
        const key = id; // dedup hanya berdasarkan ID PDF — tanggal boleh sama/duplikat
        if(candidates.has(key)){
          duplicateCount++;
        } else {
          candidates.set(key, { name: relPath, dateKey, dd, mm, yyyy, id, zipName: z.file.name, entry });
        }
      });
    }

    const uniqueList = [...candidates.values()];
    log('Ditemukan ' + uniqueList.length + ' PDF unik (' + duplicateCount + ' duplikat dilewati).', 'ok');
    await yieldUI();

    if(uniqueList.length === 0){
      throw new Error('Tidak ada PDF valid yang cocok dengan format nama di dalam ZIP yang diunggah.');
    }

    // ---- Phase 2 & 3: validate 2 pages + convert to A4 canvas ----
    const results = []; // { dateKey, idNum, idRaw, dataUrl, wmm, hmm, orientation }
    let done = 0;

    for(const cand of uniqueList){
      done++;
      const pct = 5 + (done / uniqueList.length) * 85;
      setProgress(pct);
      setStatusMsg('Memproses ' + done + ' / ' + uniqueList.length + ': ' + cand.name);
      await yieldUI();

      try{
        const arrayBuffer = await cand.entry.async('arraybuffer');
        const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;

        if(pdf.numPages !== 2){
          skipped.push({ name: cand.name, reason: 'Bukan 2 halaman (' + pdf.numPages + ')' });
          log(cand.name + ' dilewati — bukan 2 halaman (' + pdf.numPages + ').', 'warn');
          continue;
        }

        const scale = dpi / 72;
        const page1 = await pdf.getPage(1);
        const c1 = renderCanvasForPage(page1, scale);
        await drawPageToCanvas(page1, c1, scale);
        await yieldUI(); // jeda setelah render halaman 1 (operasi berat di DPI tinggi)

        const page2 = await pdf.getPage(2);
        const c2 = renderCanvasForPage(page2, scale);
        await drawPageToCanvas(page2, c2, scale);
        await yieldUI(); // jeda setelah render halaman 2

        const t1 = cropCanvas(c1, detectContentBounds(c1));
        const t2 = cropCanvas(c2, detectContentBounds(c2));
        freeCanvas(c1); // kanvas mentah tidak dipakai lagi setelah di-crop
        freeCanvas(c2);

        const finalCanvas = composeOntoA4(t1, t2, dpi);
        freeCanvas(t1); // kanvas hasil crop tidak dipakai lagi setelah digabung
        freeCanvas(t2);
        await yieldUI(); // jeda setelah compose (juga operasi berat)

        const wmm = finalCanvas.width / dpi * 25.4;
        const hmm = finalCanvas.height / dpi * 25.4;
        const dataUrl = finalCanvas.toDataURL('image/jpeg', 0.92);
        freeCanvas(finalCanvas); // sudah jadi dataUrl, kanvas besar tidak diperlukan lagi
        await yieldUI(); // jeda setelah encode JPEG (paling berat & sinkron)

        results.push({
          dateKey: cand.dateKey,
          idRaw: cand.id,
          idNum: parseInt(cand.id, 10),
          name: cand.name,
          dataUrl, wmm, hmm,
          orientation: finalCanvas.width > finalCanvas.height ? 'l' : 'p'
        });

        log(cand.name + ' berhasil dikonversi.', 'ok');
      }catch(err){
        skipped.push({ name: cand.name, reason: 'Gagal diproses (' + err.message + ')' });
        log(cand.name + ' gagal diproses: ' + err.message, 'err');
      }
    }

    if(results.length === 0){
      throw new Error('Tidak ada PDF yang berhasil dikonversi (semua dilewati).');
    }

    // ---- Phase 4: sort by date asc, then ID asc ----
    results.sort((a, b) => {
      if(a.dateKey !== b.dateKey) return a.dateKey < b.dateKey ? -1 : 1;
      const an = a.idNum, bn = b.idNum;
      if(!isNaN(an) && !isNaN(bn) && an !== bn) return an - bn;
      return a.idRaw.localeCompare(b.idRaw, undefined, { numeric:true });
    });

    // ---- Phase 5: build final combined PDF ----
    setStatusMsg('Menyusun PDF gabungan…');
    await yieldUI();

    // Susun daftar seluruh halaman final secara berurutan: cover -> daftar hadir -> isi serah terima
    const pdfPages = []; // { dataUrl, wmm, hmm, orientation }

    // ---- Halaman 1: cover (Danantara/KAI) ----
    const coverData = getCoverData();
    if(coverData.jenisDinasan && coverData.namaStasiun && coverData.bulanLabel && coverData.tahun){
      setStatusMsg('Menyiapkan halaman cover…');
      await yieldUI();
      const coverCanvas = await buildCoverCanvas(coverData, selectedDpi);
      pdfPages.push({ dataUrl: coverCanvas.toDataURL('image/jpeg', 0.95), wmm: 210, hmm: 297, orientation: 'p' });
      freeCanvas(coverCanvas);
      await yieldUI();
    }

    // ---- Halaman 2 dst: Daftar Hadir / Daftar Dinasan (landscape, auto-rotate jika potret) ----
    if(attendancePhotos.length > 0){
      for(let i = 0; i < attendancePhotos.length; i++){
        setStatusMsg('Menyiapkan Daftar Hadir ' + (i + 1) + ' / ' + attendancePhotos.length + '…');
        await yieldUI();
        try{
          const attCanvas = await buildAttendanceCanvas(attendancePhotos[i].file, selectedDpi);
          pdfPages.push({ dataUrl: attCanvas.toDataURL('image/jpeg', 0.92), wmm: 297, hmm: 210, orientation: 'l' });
          freeCanvas(attCanvas);
        }catch(err){
          log('Daftar Hadir "' + attendancePhotos[i].file.name + '" gagal diproses: ' + err.message, 'err');
        }
        await yieldUI();
      }
    }

    // ---- Halaman berikutnya: isi Serah Terima ----
    for(const r of results){
      pdfPages.push({ dataUrl: r.dataUrl, wmm: r.wmm, hmm: r.hmm, orientation: r.orientation });
    }

    const { jsPDF } = window.jspdf;
    let doc = null;
    for(const p of pdfPages){
      if(!doc){
        doc = new jsPDF({ orientation: p.orientation, unit: 'mm', format: 'a4' });
      } else {
        doc.addPage('a4', p.orientation);
      }
      doc.addImage(p.dataUrl, 'JPEG', 0, 0, p.wmm, p.hmm);
    }

    const blob = doc.output('blob');
    resultBlobUrl = URL.createObjectURL(blob);

    setProgress(100);
    setPill('done');
    setStatusMsg('Selesai — ' + results.length + ' halaman digabung.');

    renderSummary({
      totalUnique: uniqueList.length,
      duplicateCount,
      successCount: results.length,
      skipped
    });

    downloadRow.style.display = 'flex';
    resetBtn.style.display = 'inline-block';

  }catch(err){
    setPill('error');
    setStatusMsg(err.message);
    log('Proses dihentikan: ' + err.message, 'err');
    resetBtn.style.display = 'inline-block';
  }finally{
    isProcessing = false;
    processBtn.disabled = false;
    dpiOptions.style.pointerEvents = '';
  }
}

function renderSummary(info){
  let html = `
    <div class="summary-grid">
      <div class="summary-box"><div class="num">${info.totalUnique}</div><div class="lbl">PDF Unik</div></div>
      <div class="summary-box"><div class="num">${info.duplicateCount}</div><div class="lbl">Duplikat ID Dilewati</div></div>
      <div class="summary-box"><div class="num">${info.successCount}</div><div class="lbl">Berhasil Digabung</div></div>
    </div>
  `;
  if(info.skipped.length > 0){
    html += `<details class="skip-list" open>
      <summary>${info.skipped.length} file dilewati — lihat detail</summary>
      ${info.skipped.map(s => `<div class="skip-item"><span>${escapeHtml(s.name)}</span><span class="reason">${escapeHtml(s.reason)}</span></div>`).join('')}
    </details>`;
  }
  summaryEl.innerHTML = html;
  summaryEl.style.display = 'block';
}

downloadBtn.addEventListener('click', ()=>{
  if(!resultBlobUrl) return;
  const a = document.createElement('a');
  a.href = resultBlobUrl;
  a.download = 'Serah-Terima-PDF-Gabungan.pdf';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
});

/* ---- Fungsi konversi PDF -> A4 (identik dengan menu Convert per File PDF) ---- */

function renderCanvasForPage(page, scale){
  const viewport = page.getViewport({ scale });
  const c = document.createElement('canvas');
  c.width = Math.ceil(viewport.width);
  c.height = Math.ceil(viewport.height);
  return c;
}

async function drawPageToCanvas(page, c, scale){
  const viewport = page.getViewport({ scale });
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#FFFFFF';
  ctx.fillRect(0, 0, c.width, c.height);
  await page.render({ canvasContext: ctx, viewport }).promise;
}

function detectContentBounds(canvas){
  const maxDim = 800;
  const scale = Math.min(1, maxDim / Math.max(canvas.width, canvas.height));
  const tmp = document.createElement('canvas');
  tmp.width = Math.max(1, Math.round(canvas.width * scale));
  tmp.height = Math.max(1, Math.round(canvas.height * scale));
  const tctx = tmp.getContext('2d');
  tctx.drawImage(canvas, 0, 0, tmp.width, tmp.height);
  const data = tctx.getImageData(0, 0, tmp.width, tmp.height).data;

  const threshold = 248;
  let minX = tmp.width, minY = tmp.height, maxX = -1, maxY = -1;
  for(let y = 0; y < tmp.height; y++){
    for(let x = 0; x < tmp.width; x++){
      const idx = (y * tmp.width + x) * 4;
      const r = data[idx], g = data[idx+1], b = data[idx+2], a = data[idx+3];
      if(a > 10 && (r < threshold || g < threshold || b < threshold)){
        if(x < minX) minX = x;
        if(x > maxX) maxX = x;
        if(y < minY) minY = y;
        if(y > maxY) maxY = y;
      }
    }
  }

  if(maxX < minX || maxY < minY){
    return { x: 0, y: 0, width: canvas.width, height: canvas.height };
  }

  const invScale = 1 / scale;
  let x = Math.floor(minX * invScale);
  let y = Math.floor(minY * invScale);
  let w = Math.ceil((maxX - minX + 1) * invScale);
  let h = Math.ceil((maxY - minY + 1) * invScale);

  const padX = Math.round(canvas.width * 0.012);
  const padY = Math.round(canvas.height * 0.012);
  x = Math.max(0, x - padX);
  y = Math.max(0, y - padY);
  w = Math.min(canvas.width - x, w + padX * 2);
  h = Math.min(canvas.height - y, h + padY * 2);

  return { x, y, width: w, height: h };
}

function cropCanvas(canvas, bounds){
  const c = document.createElement('canvas');
  c.width = bounds.width;
  c.height = bounds.height;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#FFFFFF';
  ctx.fillRect(0, 0, c.width, c.height);
  ctx.drawImage(canvas, bounds.x, bounds.y, bounds.width, bounds.height, 0, 0, bounds.width, bounds.height);
  return c;
}

function composeOntoA4(canvas1, canvas2, dpi){
  const stackWidth = Math.max(canvas1.width, canvas2.width);
  const dividerGap = Math.round(dpi * 0.04);
  const stackHeight = canvas1.height + canvas2.height + dividerGap;

  const stack = document.createElement('canvas');
  stack.width = stackWidth;
  stack.height = stackHeight;
  const sctx = stack.getContext('2d');
  sctx.fillStyle = '#FFFFFF';
  sctx.fillRect(0, 0, stackWidth, stackHeight);
  sctx.drawImage(canvas1, (stackWidth - canvas1.width) / 2, 0);
  sctx.drawImage(canvas2, (stackWidth - canvas2.width) / 2, canvas1.height + dividerGap);

  const A4_MM = { w: 210, h: 297 };
  const isPortrait = stackHeight >= stackWidth;
  const a4wmm = isPortrait ? A4_MM.w : A4_MM.h;
  const a4hmm = isPortrait ? A4_MM.h : A4_MM.w;
  const a4w = Math.round(a4wmm / 25.4 * dpi);
  const a4h = Math.round(a4hmm / 25.4 * dpi);

  const fitScale = Math.min(a4w / stackWidth, a4h / stackHeight);
  const drawW = stackWidth * fitScale;
  const drawH = stackHeight * fitScale;
  const offsetX = (a4w - drawW) / 2;
  const offsetY = (a4h - drawH) / 2;

  const final = document.createElement('canvas');
  final.width = a4w;
  final.height = a4h;
  const fctx = final.getContext('2d');
  fctx.fillStyle = '#FFFFFF';
  fctx.fillRect(0, 0, a4w, a4h);
  fctx.imageSmoothingEnabled = true;
  fctx.imageSmoothingQuality = 'high';
  fctx.drawImage(stack, 0, 0, stackWidth, stackHeight, offsetX, offsetY, drawW, drawH);
  freeCanvas(stack); // kanvas tumpukan sementara tidak diperlukan lagi setelah dipindah ke 'final'

  return final;
}
